from decimal import Decimal, ROUND_HALF_UP, InvalidOperation

def calc_total(items: list[dict]) -> str:
    total = Decimal('0.00')
    for item in items:
        if not isinstance(item['price'], str) or not isinstance(item['qty'], int):
            raise ValueError('Invalid price or quantity type.')
        try:
            price = Decimal(item['price'])
            if not price.is_finite() or price < 0:
                raise ValueError('Price must be a nonnegative finite decimal.')
            if item['qty'] < 0:
                raise ValueError('Quantity must be a nonnegative integer.')
            total += price * item['qty']
        except (InvalidOperation, TypeError):
            raise ValueError('Invalid price or quantity value.')
    return f'{total.quantize(Decimal("0.01"), rounding=ROUND_HALF_UP)}'

