    assert apply_discount('0.00', '1.00') == '0.00'

def test_apply_discount_non_finite_inputs():
    try:
        apply_discount('inf', '0.25')
        assert False, 'ValueError not raised for non-finite amount'
    except ValueError:
        pass

    try:
        apply_discount('100.00', 'NaN')
        assert False, 'ValueError not raised for non-finite rate'
    except ValueError:
        pass

