    try:
        apply_discount('100.00', '-0.25')
        assert False, 'ValueError not raised for negative rate'
    except ValueError:
        pass

    try:
        apply_discount('100.00', '1.25')
        assert False, 'ValueError not raised for rate greater than 1'
    except ValueError:
        pass

