from math import ceil

def paginate(items: list, page: int, size: int) -> dict:
    """Return a page, with proper indexing, validation, and handling of edge cases."""
    if not isinstance(page, int) or not isinstance(size, int):
        raise ValueError("Both 'page' and 'size' must be integers.")
    if isinstance(page, bool) or isinstance(size, bool):
        raise ValueError("Both 'page' and 'size' must be integers, not booleans.")
    if page < 1:
        raise ValueError("Page number must be at least 1.")
    if size < 1 or size > 100:
        raise ValueError("Page size must be between 1 and 100 inclusive.")

    total = len(items)
    pages = ceil(total / size) if total > 0 else 0
    start_index = (page - 1) * size
    end_index = start_index + size

    if start_index >= total:
        return {'items': [], 'total': total, 'pages': pages}

    return {
        'items': items[start_index:end_index],
        'total': total,
        'pages': pages
    }

