from fastapi import FastAPI, HTTPException
from pydantic import BaseModel, conint, confloat, condecimal
from decimal import Decimal, getcontext, ROUND_HALF_UP

getcontext().rounding = ROUND_HALF_UP

app = FastAPI()

class QuoteRequest(BaseModel):
    unitPrice: condecimal(gt=-1, max_digits=10, decimal_places=2)  # Finite and non-negative
    quantity: conint(gt=0, le=100)  # Strictly integer between 1 and 100

@app.post('/quote')
async def quote(request: QuoteRequest):
    if not request.unitPrice.is_finite():
        raise HTTPException(status_code=422, detail='unitPrice must be a finite number.')
    total = (request.unitPrice * request.quantity).quantize(Decimal('0.01'))
    return {'total': str(total)}

@app.get('/health')
async def health():
    return {'status': 'ok'}

import pytest
from fastapi.testclient import TestClient
from app.quote_eval import app

class TestQuoteEval:
    @pytest.fixture
    def client(self):
        return TestClient(app)

    def test_health_check(self, client):
        response = client.get('/health')
        assert response.status_code == 200
        assert response.json() == {'status': 'ok'}

    @pytest.mark.parametrize(
        'payload, expected_status, expected_response', [
            ({'unitPrice': '1.99', 'quantity': 5}, 200, {'total': '9.95'}),
            ({'unitPrice': '0.00', 'quantity': 100}, 200, {'total': '0.00'}),
            ({'unitPrice': '-0.01', 'quantity': 1}, 422, None),  # Negative price
            ({'unitPrice': '1.99', 'quantity': 101}, 422, None),  # Quantity too high
            ({'unitPrice': '1.99', 'quantity': 0}, 422, None),  # Quantity too low
            ({'unitPrice': 'abc', 'quantity': 5}, 422, None),  # Invalid price format
            ({'unitPrice': '1.99', 'quantity': True}, 422, None),  # Boolean quantity
            ({'unitPrice': '1.99'}, 422, None),  # Missing quantity field
            ({'quantity': 5}, 422, None),  # Missing unitPrice field
        ]
    )
    def test_quote(self, client, payload, expected_status, expected_response):
        response = client.post('/quote', json=payload)
        assert response.status_code == expected_status
        if expected_response is not None:
            assert response.json() == expected_response

if __name__ == '__main__':
    pytest.main([__file__])

