import math


def paginate(items: list, page: int, size: int) -> dict:
    if not isinstance(page, int) or not isinstance(size, int) or isinstance(page, bool) or isinstance(size, bool):
        raise ValueError('Page and size must be integers and cannot be booleans.')
    if page < 1 or size < 1 or size > 100:
        raise ValueError('Page must be >= 1 and size must be between 1 and 100 inclusive.')
    total = len(items)
    pages = math.ceil(total / size) if total else 0
    start_index = (page - 1) * size
    end_index = start_index + size
    if start_index >= total or end_index > total:
        sliced_items = []
