from decimal import Decimal, ROUND_HALF_UP

class EventLedger:
    def __init__(self):
        self.ledger = {}

    def apply(self, event_id: str, amount: str) -> bool:
        if not event_id:
            raise ValueError('Event ID must be non-empty.')
        try:
            amount_decimal = Decimal(amount)
            if not amount_decimal.is_finite() or amount_decimal < 0:
                raise ValueError
        except (ValueError, ArithmeticError):
            raise ValueError('Amount must be a nonnegative, finite Decimal.')

        if event_id in self.ledger:
            if self.ledger[event_id] == amount_decimal:
                return False
            else:
                raise ValueError('Event ID reused with a different amount.')
        else:
            self.ledger[event_id] = amount_decimal
            return True

    def total(self) -> str:
        total_amount = sum(self.ledger.values(), Decimal('0'))
        return f'{total_amount.quantize(Decimal('0.01'), rounding=ROUND_HALF_UP)}'

