from fastapi import FastAPI, HTTPException
from pydantic import BaseModel
from decimal import Decimal, ROUND_HALF_UP

app = FastAPI()

class QuoteRequest(BaseModel):
    unitPrice: str
    quantity: int

@app.post('/quote')
async def quote(request: QuoteRequest):
    try:
        price = Decimal(request.unitPrice)
        if not price.is_finite() or price < 0:
            raise ValueError('Invalid unit price.')
        if not 1 <= request.quantity <= 100 or isinstance(request.quantity, bool):
            raise ValueError('Quantity must be an integer between 1 and 100.')
        total = (price * request.quantity).quantize(Decimal('0.01'), rounding=ROUND_HALF_UP)
        return {'total': str(total)}
    except Exception as e:
        raise HTTPException(status_code=422, detail=str(e))

@app.get('/health')
async def health():
    return {'status': 'ok'}

