from fastapi.testclient import TestClient
from app.quote_eval import app
import pytest

client = TestClient(app)

def test_health():
    response = client.get('/health')
    assert response.status_code == 200
    assert response.json() == {'status': 'ok'}

def test_quote_valid():
    response = client.post('/quote', json={'unitPrice': '1.99', 'quantity': 5})
    assert response.status_code == 200
    assert response.json() == {'total': '9.95'}

def test_quote_invalid_unit_price():
    response = client.post('/quote', json={'unitPrice': '-0.01', 'quantity': 1})
    assert response.status_code == 422

def test_quote_invalid_quantity():
    response = client.post('/quote', json={'unitPrice': '1.00', 'quantity': 101})
    assert response.status_code == 422

def test_quote_missing_fields():
    response = client.post('/quote', json={})
    assert response.status_code == 422

