import time
from typing import Callable, TypeVar, Any

T = TypeVar('T')


def retry_call(operation: Callable[[], T], *, attempts: int = 3, base_delay: float = 0.1, sleep: Callable[[float], None] = time.sleep) -> T:
    """
    Call the operation with no arguments and return its result. Retry on ConnectionError and TimeoutError,
    for a total of at most `attempts` calls. Before each retry (except the first), wait for an increasing delay
    calculated as `base_delay * 2 ** retry_index`. Do not sleep after the final failure.

    If the maximum number of attempts is reached without success, propagate the last encountered exception.

    :param operation: The function to call, which takes no arguments and returns a value of type T.
    :param attempts: The maximum number of attempts to make, must be a positive integer (not bool).
    :param base_delay: The base delay in seconds before the first retry, must be finite and non-negative.
    :param sleep: A sleep function that takes a single argument, the number of seconds to sleep. Defaults to time.sleep.
    :return: The result of the operation if it succeeds within the allowed attempts.
    :raises ValueError: If `attempts` is not a positive integer or `base_delay` is not finite and non-negative.
    :raises: The original exception from the operation if all attempts fail.
    """
    if not isinstance(attempts, int) or attempts <= 0:
        raise ValueError("'attempts' must be a positive integer.")
    if not (isinstance(base_delay, (int, float)) and base_delay >= 0 and base_delay != float('inf')):
        raise ValueError("'base_delay' must be finite and non-negative.")

    for attempt in range(attempts):
        try:
            return operation()
        except (ConnectionError, TimeoutError) as e:
            if attempt < attempts - 1:
                sleep(base_delay * 2 ** attempt)
            else:
                raise e

